using Godot;
using System;
using System.Linq;
using System.Globalization;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class KeyframeCanvasOperations:RefCounted
{
    private const float LabelWidth=140,Header=56;private readonly ActorTimelineOperations _timeline=new();private readonly TimelineCanvasOperations _canvas=new();
    private static RefCounted Model(Control owner)=>owner.Get("model").As<RefCounted>();private static Control Timeline(Control owner)=>owner.Get("timeline").As<Control>();private static Resource? Actor(Control owner)=>owner.Get("actor").As<Resource>();private static GArray Selected(Control owner)=>owner.Get("selected_keys").AsGodotArray();private static bool Overlay(Control owner)=>owner.Get("overlay_mode").AsBool();
    public double track_height(Control owner)=>Timeline(owner).Get("row_height").AsDouble()*30/48;
    public double header_height(Control owner)=>owner.Get("show_ruler").AsBool()?Header:0;
    public Rect2 selection_box(Control owner)=>new Rect2(owner.Get("_box_start").AsVector2(),owner.Get("_box_end").AsVector2()-owner.Get("_box_start").AsVector2()).Abs();
    public GArray displayed_tracks(Control owner){var actor=Actor(owner);if(actor==null)return new GArray();var tracks=actor.Get("animation_tracks").AsGodotArray();if(!Overlay(owner))return tracks;var result=tracks.Duplicate();result.Clear();foreach(var value in tracks)if(value.As<Resource>().Get("path").AsStringArray().SequenceEqual(Model(owner).Get("overlay_path").AsStringArray()))result.Add(value);return result;}
    public Rect2 overlay_rect(Control owner){var actor=Actor(owner);if(actor==null)return new Rect2();var model=Model(owner);var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(clip==null)return new Rect2();int index=model.Get("clips").AsGodotArray().IndexOf(clip);return index>=0&&_timeline.clip_is_visible(model,index)?_canvas.clip_rect(Timeline(owner),index):new Rect2();}
    public void ready(Control owner){owner.FocusMode=Control.FocusModeEnum.All;owner.MouseDefaultCursorShape=Control.CursorShape.PointingHand;}
    public void update_box(Control owner,bool add,bool subtract){var selected=Selected(owner);selected.Clear();if(add||subtract)foreach(var id in owner.Get("_box_base").AsGodotArray())selected.Add(id);var tracks=displayed_tracks(owner);var actor=Actor(owner);if(actor!=null){var clip=_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString());if(clip!=null){var rect=overlay_rect(owner);var box=selection_box(owner);for(int row=0;row<tracks.Count;row++)foreach(var value in tracks[row].As<Resource>().Get("keys").AsGodotArray()){var key=value.As<Resource>();if(!box.HasPoint(Position(owner,clip,key,row,tracks.Count,rect)))continue;if(subtract)selected.Remove(key.Get("id"));else if(!selected.Contains(key.Get("id")))selected.Add(key.Get("id"));}}}owner.EmitSignal("selection_changed");owner.QueueRedraw();}
    public void cancel_drag(Control owner){if(owner.Get("box_selecting").AsBool()){owner.Set("box_selecting",false);var selected=Selected(owner);selected.Clear();foreach(var id in owner.Get("_box_base").AsGodotArray())selected.Add(id);owner.EmitSignal("selection_changed");owner.EmitSignal("interaction_changed","");owner.QueueRedraw();}if(owner.Get("_scrubbing").AsBool()){owner.Set("_scrubbing",false);Timeline(owner).EmitSignal("time_selected",owner.Get("_scrub_origin"));}if(!owner.Get("_dragging").AsBool())return;owner.Set("_dragging",false);owner.Set("_delta",0.0);owner.Get("_original_times").AsGodotDictionary().Clear();owner.EmitSignal("interaction_changed","");owner.QueueRedraw();}
    private Vector2 Position(Control owner,Resource clip,Resource key,int row,int trackCount,Rect2 overlay)
    {
        bool dragging=owner.Get("_dragging").AsBool()&&Selected(owner).Contains(key.Get("id"));double source=dragging?owner.Get("_original_times").AsGodotDictionary().GetValueOrDefault(key.Get("id"),key.Get("time")).AsDouble():key.Get("time").AsDouble();double time=clip.Get("start_time").AsDouble()+(source-clip.Get("source_offset").AsDouble())/clip.Get("playback_speed").AsDouble();if(dragging)time+=owner.Get("_delta").AsDouble();var timeline=Timeline(owner);return new Vector2((float)(LabelWidth+(time-timeline.Get("scroll_time").AsDouble())*timeline.Get("pixels_per_second").AsDouble()),Overlay(owner)?overlay.Position.Y+overlay.Size.Y*(row+1)/(trackCount+1):(float)(header_height(owner)+row*track_height(owner)+track_height(owner)/2));
    }
    public Vector2 key_position(Control owner,Resource key,int row){var actor=Actor(owner);var clip=actor!=null?_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString()):null;return clip!=null?Position(owner,clip,key,row,displayed_tracks(owner).Count,overlay_rect(owner)):Vector2.Inf;}
    public string tooltip(Control owner,Vector2 position){var actor=Actor(owner);if(actor==null)return "";var clip=_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString());if(clip==null)return "";var tracks=displayed_tracks(owner);var overlay=overlay_rect(owner);for(int row=0;row<tracks.Count;row++){var track=tracks[row].As<Resource>();if(!Overlay(owner)&&position.X<LabelWidth&&(int)((position.Y-header_height(owner))/track_height(owner))==row)return track.Get("label").AsString()+"\n"+string.Join(" / ",track.Get("path").AsStringArray());foreach(var value in track.Get("keys").AsGodotArray()){var key=value.As<Resource>();if(Position(owner,clip,key,row,tracks.Count,overlay).DistanceTo(position)<10)return track.Get("label").AsString()+"\nValue: "+key.Get("value").ToString()+"\nSource time: "+key.Get("time").AsDouble().ToString("F2",CultureInfo.InvariantCulture)+"s";}}return "";}
    public StyleBoxFlat clip_style(){var style=new StyleBoxFlat{BgColor=new Color("28554f"),BorderColor=new Color("72cfb8")};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(4);return style;}
}
